& -\Psi^{\prime}=F^{\prime} \frac{\delta x}{\delta t}+G \frac{\delta y}{\delta t}+H \frac{\delta z}{\delta t}  \tag{6}\\
& \frac{d \boldsymbol{F}^{\prime}}{d t}=-\frac{d \Psi^{\prime}}{d x}-c \frac{\delta y}{\delta t}+b \frac{\delta z}{\delta t}+\frac{d \boldsymbol{F}}{d t} \tag{7}
\end{align*}$$


